void eraseAll(string& s, const string& two) {
    size_t at;
    while ((at = s.find(two)) != string::npos) s.erase(at, 2);
}

bool isValid(string s) {
    string prev;
    do {                                // stop when a pass removes nothing
        prev = s;
        eraseAll(s, "()");
        eraseAll(s, "[]");
        eraseAll(s, "{}");
    } while (s != prev);
    return s.empty();
}

