public boolean isValid(String s) {
    Map<Character, Character> pairs = Map.of(')', '(', ']', '[', '}', '{');
    Deque<Character> stack = new ArrayDeque<>();
    for (char c : s.toCharArray()) {
        if (c == '(' || c == '[' || c == '{') {
            stack.push(c);                 // remember it's open
        } else if (stack.isEmpty() || !stack.pop().equals(pairs.get(c))) {
            return false;
        }
    }
    return stack.isEmpty();                // nothing may be left open
}

bool isValid(const string& s) {
    unordered_map<char, char> pairs = {{')', '('}, {']', '['}, {'}', '{'}};
    stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);                    // remember it's open
        } else {
            if (st.empty() || st.top() != pairs[c]) return false;
            st.pop();
        }
    }
    return st.empty();                     // nothing may be left open
}

function isValid(s) {
  if (s.length % 2 === 1) return false;      // odd length can't pair up
  const expect = [];                          // closers we still owe
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === "(") expect.push(")");
    else if (c === "[") expect.push("]");
    else if (c === "{") expect.push("}");
    else if (expect.pop() !== c) return false;   // wrong closer, or none owed
    if (expect.length > s.length - 1 - i) return false;   // can't close them all in time
  }
  return expect.length === 0;
}

