public boolean isValid(String s) {
    if (s.length() % 2 == 1) return false;    // odd length can't pair up
    Deque<Character> expect = new ArrayDeque<>();   // closers we still owe
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') expect.push(')');
        else if (c == '[') expect.push(']');
        else if (c == '{') expect.push('}');
        else if (expect.isEmpty() || expect.pop() != c) return false;   // wrong closer, or none owed
        if (expect.size() > s.length() - 1 - i) return false;           // can't close them all in time
    }
    return expect.isEmpty();
}

