    for (size_t i = 0; i < s.size(); i++) {
        char c = s[i];
        if (c == '(') expect.push_back(')');
        else if (c == '[') expect.push_back(']');
        else if (c == '{') expect.push_back('}');
        else {
            if (expect.empty() || expect.back() != c) return false;   // wrong closer, or none owed
            expect.pop_back();
        }
